<script setup lang="ts">
import {indicatorHelp} from '../utils/indicatorHelp'
const {feedbackTarget,captureAction}=useActionFeedback()
const props=defineProps<{game:any;targetType:string;targetId:string;compact?:boolean}>(),emit=defineEmits(['changed','processing'])
const data=ref<any>(null),error=ref(''),busy=ref(false),review=ref(''),history=ref<any[]>([]),offset=ref(0),expanded=ref(false)
const labels:any={stability:'Estabilidade',security:'Segurança',economy:'Economia',tension:'Tensão',difficulty:'Dificuldade',risk:'Risco'},levels=['Desconhecido','Preliminar','Verificado','Detalhado']
const commandStore=useState<Record<string,any>>('intelligence-commands',()=>({})),pending=computed({get:()=>commandStore.value[props.game.id]??null,set:(v:any)=>commandStore.value={...commandStore.value,[props.game.id]:v}}),locked=computed(()=>busy.value||!!pending.value)
const base=()=>'/api/v1/games/'+props.game.id+'/intelligence',query=()=>'?targetType='+props.targetType+'&targetId='+encodeURIComponent(props.targetId)
function activeAnalysis(topic:string){
 return data.value?.analyses.find((job:any)=>job.topic===topic&&['scheduled','pending'].includes(job.status))
}
const topics=computed(()=>Object.values(data.value?.topics??{}).map((topic:any)=>({...topic,activeAnalysis:activeAnalysis(topic.topic)})))
const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(n/100)
let refreshSerial=0
async function refresh(){const serial=++refreshSerial,scope=base()+query();try{const next=await $fetch<any>(scope+'&limit=10');if(serial!==refreshSerial||scope!==base()+query())return false;data.value=next;history.value=data.value.history;offset.value=history.value.length;return true}catch(e:any){if(serial!==refreshSerial||scope!==base()+query())return false;error.value=e.data?.message||'Não foi possível carregar a inteligência.';return false}}
async function more(){try{const page=await $fetch<any>(base()+query()+'&limit=10&offset='+offset.value);history.value.push(...page.history);offset.value+=page.history.length;data.value.pagination=page.pagination}catch{error.value='Não foi possível carregar o histórico.'}}
async function run(){if(busy.value||(!pending.value&&(!review.value||activeAnalysis(review.value))))return;const command=pending.value||{requestId:crypto.randomUUID(),expectedVersion:data.value.stateVersion,targetType:props.targetType,targetId:props.targetId,topic:review.value};pending.value=command;busy.value=true;emit('processing',true);error.value='';let done=false;try{await $fetch(base()+'/analyses',{method:'POST',body:command});if(!await refresh())return;pending.value=null;review.value='';done=true}catch(e:any){if(e.status>=400&&e.status<500){pending.value=null;review.value='';await refresh()}error.value=e.data?.message||'Falha de conexão. Repita para recuperar a mesma análise.'}finally{busy.value=false;emit('processing',!!pending.value)}if(done)emit('changed')}
watch(()=>[props.game.id,props.game.stateVersion,props.targetType,props.targetId],async()=>{review.value='';data.value=null;await refresh()})
onMounted(async()=>{emit('processing',!!pending.value);await refresh()})
</script>
<template><section class="intel-panel" :class="{'intel-integrated':compact}" @click.capture="captureAction($event);error=''"><div v-if="!compact" class="panel-heading"><h3>Inteligência da companhia</h3><span class="tag">ESTIMATIVAS</span></div><p v-if="!compact">Uma análise busca uma estimativa mais precisa para ajudar no planejamento. Ela não altera as condições do país nem torna a missão mais segura. Fontes podem divergir, e a informação perde confiança com o tempo.</p><details class="intel-guide"><summary>Como ler as estimativas e quando analisar?</summary><p>A faixa listrada indica a avaliação disponível, de 0 a 100. Quanto mais estreita, mais precisa é a estimativa; ela ainda pode divergir da situação real.</p><p>Confiança mede a qualidade da informação, não a chance de sucesso da missão. O nível descreve o detalhamento: preliminar, verificado ou detalhado. Mesmo uma fonte verificada pode estar desatualizada.</p><p>Considere uma análise quando a informação estiver antiga, as fontes divergirem ou a incerteza pesar na sua decisão. O relatório pode trazer uma faixa diferente da anterior.<template v-if="data"> Prazo estimado: {{formatCampaignDuration(data.analysis.turns)}}.</template></p></details><ActionFeedback :target="feedbackTarget" :section="targetType + ':' + targetId" :turn="game.currentTurn" v-model:error="error" />
 <div v-if="pending&&!busy" class="panel intel-retry"><p>Análise aguardando confirmação. Repetir mantém o mesmo pedido e débito.</p><button class="primary" @click="run">Repetir solicitação</button></div>
 <template v-if="data"><div class="intel-topics"><article v-for="t in topics" :key="t.topic" data-action-card :id="'intelligence-'+targetId+'-'+t.topic" class="intel-topic"><div class="panel-heading"><strong>{{labels[t.topic]}} · {{levels[t.level]}}</strong><span v-if="t.conflicting" class="tag">FONTES CONFLITANTES</span><span v-else-if="t.stale" class="tag">OBSOLETA</span></div><IntelligenceEstimate :label="labels[t.topic]" :estimate="t.estimate" :confidence="t.confidence" :inverse="['tension','difficulty','risk'].includes(t.topic)"><p class="indicator-help">{{indicatorHelp[t.topic]}}</p></IntelligenceEstimate>
 <p v-if="t.activeAnalysis" role="status">{{t.activeAnalysis.status==='scheduled'?'Análise agendada':'Análise em andamento'}}<template v-if="t.activeAnalysis.dueTurn!=null"> · entrega prevista para {{formatCampaignTurn(game,t.activeAnalysis.dueTurn)}}</template>.</p>
 <button class="secondary" :disabled="locked||game.cashCents<data.analysis.costCents||!!t.activeAnalysis" @click="review=t.topic">Analisar {{labels[t.topic].toLowerCase()}} · {{money(data.analysis.costCents)}}</button> <FocusDialog v-if="review===t.topic" title="Solicitar análise" :busy="busy" :error="error" @close="review=''"><section class="inline-action decision-card analysis-confirm"><h3>Solicitar análise de {{labels[review].toLowerCase()}}?</h3><p>Custo ao confirmar: {{money(data.analysis.costCents)}}. Entrega prevista para {{formatCampaignTurn(game,game.currentTurn+data.analysis.turns)}} se confirmar. Duas análises simultâneas por companhia. Não há reembolso automático; o relatório pode divergir de outras fontes.</p><div class="personnel-actions"><button class="primary" :disabled="locked||!!t.activeAnalysis" @click="run">Agendar análise</button><button class="secondary" :disabled="locked" @click="review=''">Voltar</button></div></section></FocusDialog></article></div>

 <button class="secondary intel-history" @click="expanded=!expanded">{{expanded?'Ocultar histórico':'Histórico de conhecimento'}}</button><FocusDialog v-if="expanded" title="Histórico de conhecimento" :busy="busy" :error="error" @close="expanded=false"><div class="intel-history-content"><article v-for="r in history" :key="r.id" class="mission-report"><span class="eyebrow">{{labels[r.topic]}} · {{r.sourceName}}</span><EstimateBar :label="labels[r.topic]+' · registro histórico'" :min="r.estimate.min" :max="r.estimate.max" :inverse="['tension','difficulty','risk'].includes(r.topic)" /><p>{{levels[r.collectedLevel]}} na coleta<br>Coletada em {{formatCampaignTurn(game,r.collectedTurn,true)}} · válida até {{formatCampaignTurn(game,r.validUntilTurn)}} · confiança atual {{r.confidence}}%<span v-if="r.stale"> · obsoleta</span><br><span v-if="r.supersedesId">Atualiza registro anterior desta fonte.</span></p></article><button v-if="data.pagination.hasMore" class="secondary" @click="more">Carregar mais registros</button></div></FocusDialog>
 </template><p v-else>Carregando conhecimento…</p></section></template>

<style scoped>
.analysis-confirm{padding:16px;border:1px solid #574329;border-radius:12px;max-width:100%;box-sizing:border-box}.analysis-confirm h3{margin:0!important;font-size:var(--text-subtitle);line-height:1.4}.analysis-confirm p{margin:12px 0;line-height:1.6}.analysis-confirm .personnel-actions{position:static;bottom:auto;z-index:auto;background:transparent;padding:0;margin-top:16px;display:flex;flex-direction:row;gap:10px}.analysis-confirm .personnel-actions>button{min-width:0;flex:1;margin:0;padding:12px 10px;white-space:normal}

.intel-panel.intel-integrated{padding:0;border:0;border-radius:0;background:transparent;margin:24px 0}
.intel-guide{margin:16px 0}.intel-guide summary{cursor:pointer;min-height:44px;font-size:var(--text-body)}.intel-guide p{font-size:var(--text-body);margin-bottom:12px}
.intel-integrated .intel-topics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:24px 0}.intel-integrated .intel-topic{min-width:0;padding:16px;border:1px solid #30363c;background:#161a1e}.intel-integrated .intel-topic>.panel-heading{padding-bottom:12px;margin-bottom:16px;flex-wrap:wrap}.intel-integrated .intel-topic p{font-size:var(--text-caption)}@media(max-width:600px){.intel-integrated .intel-topics{grid-template-columns:1fr}}
.indicator-help{font-size:var(--text-body);margin:14px 0}.intel-topic>details{margin:16px 0}.intel-topic>button,.intel-retry>button,.intel-panel>.intel-history,.intel-history-content>button{display:block;width:100%;margin-top:var(--space-4);text-align:center;white-space:normal}

.intel-panel,.intel-panel.intel-integrated{margin:var(--space-4) 0;padding:var(--space-4)}
.intel-panel.intel-integrated{padding:0}
.intel-topic{padding:var(--space-4) 0}
.intel-topic p,.intel-integrated .intel-topic p,.intel-guide p{font-size:var(--text-body);line-height:1.5;margin:var(--space-3) 0}

.intel-guide>summary{font-size:var(--text-body);line-height:1.5;font-weight:600;min-height:44px;padding:var(--space-3) 0;cursor:pointer}
.intel-guide{margin:var(--space-3) 0}

.intel-integrated .intel-topics{gap:var(--space-4);margin:var(--space-4) 0}
.analysis-confirm h3{font-size:var(--text-subtitle)}
</style>
